(() => {
 const $=id=>document.getElementById(id), config=window.SIPANTIP_ANALYTICS;
 let token=null, expires=0;
 const number=n=>Number(n||0).toLocaleString('id-ID');
 const date=value=>value?new Date(value).toLocaleString('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'})+' WIB':'Belum ada';
 const labels={'peta-section':'Peta sebaran','district-section':'Per kecamatan','village-section':'Per desa','daily-section':'Laporan harian','pm-section':'PM 2.5','data-section':'Daftar titik panas','regency-section':'Per kabupaten','langsung':'Langsung / tidak diketahui','internal':'Dari website ini'};
 function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
 async function request(path,body,auth){const response=await fetch(config.url+path,{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+auth}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});if(!response.ok){const e=new Error('Permintaan gagal');e.status=response.status;try{const detail=await response.json();e.code=detail.error_code||detail.code||'';}catch{}throw e;}return response.status===204?null:response.json();}
 function signout(){token=null;expires=0;$('adminReport').hidden=true;$('loginPanel').hidden=false;$('reportBody').replaceChildren();$('adminPassword').value='';}
 function breakdown(title,rows){const card=el('section',undefined,'panel');card.append(el('h2',title));if(!rows.length){card.append(el('p','Belum ada kunjungan.','caption'));return card;}const max=Math.max(...rows.map(r=>Number(r.count)),1);rows.forEach(r=>{const row=el('div',undefined,'stat-row'),head=el('div',undefined,'stat-row-label');head.append(el('span',labels[r.label]||String(r.label)),el('b',number(r.count)));const track=el('div',undefined,'stat-track'),bar=el('i');bar.style.width=(Number(r.count)/max*100)+'%';track.append(bar);row.append(head,track);card.append(row);});return card;}
 function render(data){
  const root=$('reportBody');root.replaceChildren();const cards=el('div',undefined,'analytics-metrics');
  [['Total pengunjung',data.totals.total,'Sejak pencatatan aktif'],['Pengunjung hari ini',data.totals.today,'Hari kalender WIB'],['Pengunjung unik',data.unique,'Pada rentang terpilih'],['Kunjungan',data.sessions,'Sesi pada rentang terpilih'],['Halaman dibuka',data.views,'Termasuk kunjungan ulang']].forEach(([title,value,hint])=>{const c=el('article',undefined,'panel');c.append(el('span',title,'caption'),el('strong',number(value)),el('small',hint));cards.append(c);});root.append(cards);
  const daily=el('section',undefined,'panel');daily.append(el('h2','Kunjungan harian'));const wrap=el('div',undefined,'table-wrap'),table=el('table'),thead=el('thead'),tr=el('tr');['Tanggal (WIB)','Pengunjung unik','Kunjungan','Halaman dibuka'].forEach(t=>tr.append(el('th',t)));thead.append(tr);table.append(thead);const tbody=el('tbody');const map=new Map(data.daily.map(r=>[r.day,r]));const startDay=data.totals.since?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(data.totals.since)):null;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());for(let i=0;i<Number($('reportDays').value);i++){const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-i);const key=d.toISOString().slice(0,10),r=map.get(key),row=el('tr');[key,...(!startDay||key<startDay?['Belum tercatat','—','—']:[number(r?.visitors),number(r?.sessions),number(r?.views)])].forEach(t=>row.append(el('td',t)));tbody.append(row);}table.append(tbody);wrap.append(table);daily.append(wrap);root.append(daily);
  const grid=el('div',undefined,'analytics-grid');grid.append(breakdown('Perangkat',data.devices),breakdown('Browser',data.browsers),breakdown('Sistem operasi',data.systems),breakdown('Asal tautan',data.referrers),breakdown('Fitur dilihat',data.features),breakdown('Jam kunjungan (WIB)',data.hours.map(r=>({...r,label:String(r.label).padStart(2,'0')+'.00'}))));root.append(grid);
  root.append(el('p','Mulai tercatat: '+date(data.totals.since)+' · Kunjungan terakhir: '+date(data.latest),'caption'));
 }
 async function load(){
  $('reportStatus').textContent='Mengambil statistik…';$('reloadReport').disabled=true;
  try{if(Date.now()>=expires){signout();$('loginStatus').textContent='Sesi berakhir. Silakan masuk kembali.';return;}const data=await request('/rest/v1/rpc/visitor_report',{p_days:Number($('reportDays').value)},token);render(data);$('reportStatus').textContent='Diperbarui '+date(new Date());}
  catch(e){$('reportBody').replaceChildren();if(e.status===401||e.status===403){signout();$('loginStatus').textContent='Akun belum memiliki akses admin atau sesi sudah berakhir.';}else $('reportStatus').textContent='Statistik gagal dimuat. Tekan Perbarui untuk mencoba lagi.';}
  finally{$('reloadReport').disabled=false;}
 }
 $('adminLogin').addEventListener('submit',async e=>{e.preventDefault();$('loginButton').disabled=true;$('loginStatus').textContent='Memeriksa akun…';try{const data=await request('/auth/v1/token?grant_type=password',{email:$('adminEmail').value.trim(),password:$('adminPassword').value});token=data.access_token;expires=Date.now()+data.expires_in*1000;$('adminPassword').value='';$('loginPanel').hidden=true;$('adminReport').hidden=false;await load();}catch(error){const messages={invalid_credentials:'Email atau password tidak cocok. Gunakan password akun pengguna yang dibuat melalui Create user di Supabase, bukan password database.',email_not_confirmed:'Email akun belum dikonfirmasi. Periksa pengaturan pengguna di Supabase.',over_request_rate_limit:'Terlalu banyak percobaan. Tunggu sebentar sebelum mencoba lagi.'};$('loginStatus').textContent=messages[error.code]||(error.status===429?'Terlalu banyak percobaan. Tunggu sebentar sebelum mencoba lagi.':error.status?'Login ditolak layanan autentikasi (HTTP '+error.status+'). Silakan coba lagi.':'Tidak dapat menghubungi layanan login. Periksa koneksi lalu coba lagi.');}finally{$('loginButton').disabled=false;}});
 $('logoutButton').onclick=async()=>{const current=token;signout();$('loginStatus').textContent='Sudah keluar.';try{await request('/auth/v1/logout',{},current);}catch{}};
 $('reloadReport').onclick=load;$('reportDays').onchange=load;
})();
